expected = {a['number'] for a in sources}
assert expected == set(drafts), (expected - set(drafts), set(drafts) - expected)
answer = []
for source in sources:
    item = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(drafts[source['number']])
    answer.append(item)
with open('answer.json', 'w', encoding='utf-8') as f:
    json.dump(answer, f, ensure_ascii=False, indent=2)
    f.write('\n')
print('answer.json :', len(answer), 'articles')
